package vn.smartprop.modules.legal;
import java.time.*;
import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import vn.smartprop.modules.auth.AccountAccess;
import vn.smartprop.modules.audit.BusinessAuditWriter;
import vn.smartprop.common.*;
import vn.smartprop.config.*;
import vn.smartprop.modules.media.LocalFileStore;
import vn.smartprop.modules.property.*;
import vn.smartprop.modules.user.User;
@Service
@Transactional(readOnly=true)
public class LegalDocumentService {
    private final JdbcTemplate jdbc;private final AccountAccess access;private final PropertyRepository properties;private final LocalFileStore files;private final LegalPdfValidator pdf;private final BusinessAuditWriter audit;private final boolean enabled;
    public record View(String id,String propertyId,String documentType,String documentNumber,LocalDate issueDate,String ownerName,String originalFilename,String mimeType,long sizeBytes,int contentVersion,String status,Long reviewedBy,String reviewReason,Instant reviewedAt,Instant createdAt,Instant updatedAt) {@Override public String toString(){return "LegalDocument[redacted]";}}
    private record Stored(View view,String key) {}
    public LegalDocumentService(JdbcTemplate jdbc,AccountAccess access,PropertyRepository properties,LocalFileStore files,LegalPdfValidator pdf,BusinessAuditWriter audit,@Value("${app.legal-documents.enabled:false}") boolean enabled){this.jdbc=jdbc;this.access=access;this.properties=properties;this.files=files;this.pdf=pdf;this.audit=audit;this.enabled=enabled;}
    private void ready(){if(!enabled)throw new ApiException(503,"FEATURE_DISABLED","Legal documents disabled");}
    private Property allowed(Long actor,String propertyId,boolean write){User u=access.active(actor);ready();Property p=(write?properties.lockById(ApiInputs.uuid(propertyId)):properties.findById(ApiInputs.uuid(propertyId))).orElseThrow(ApiInputs::missing);boolean owner=Objects.equals(p.ownerId,actor);if(write&&!owner||!write&&!owner&&u.role!=User.Role.ADMIN)throw ApiInputs.missing();if(p.deletedAt!=null&&(write||u.role!=User.Role.ADMIN))throw ApiInputs.missing();return p;}
    private static Instant instant(java.sql.ResultSet r,String column)throws java.sql.SQLException{var v=r.getTimestamp(column);return v==null?null:v.toInstant();}
    private org.springframework.jdbc.core.RowMapper<Stored> mapper(){return (r,n)->new Stored(new View(r.getString("id"),r.getString("property_id"),r.getString("document_type"),r.getString("document_number"),r.getObject("issue_date",LocalDate.class),r.getString("owner_name"),r.getString("original_filename"),r.getString("mime_type"),r.getLong("size_bytes"),r.getInt("content_version"),r.getString("status"),r.getObject("reviewed_by",Long.class),r.getString("review_reason"),instant(r,"reviewed_at"),instant(r,"created_at"),instant(r,"updated_at")),r.getString("storage_key"));}
    private Stored stored(String property,String id,boolean lock){return jdbc.query("SELECT * FROM property_legal_documents WHERE id=? AND property_id=? AND deleted_at IS NULL"+(lock?" FOR UPDATE":""),mapper(),ApiInputs.uuid(id),property).stream().findFirst().orElseThrow(ApiInputs::missing);}
    public PageResponse<View> list(Long actor,String property,int page,int size){property=ApiInputs.uuid(property);allowed(actor,property,false);ApiInputs.newest(page,size);long total=jdbc.queryForObject("SELECT COUNT(*) FROM property_legal_documents WHERE property_id=? AND deleted_at IS NULL",Long.class,property);var items=jdbc.query("SELECT * FROM property_legal_documents WHERE property_id=? AND deleted_at IS NULL ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",mapper(),property,size,(long)page*size).stream().map(Stored::view).toList();return new PageResponse<>(items,page,size,total,(int)((total+size-1)/size));}
    public View detail(Long actor,String property,String id){property=ApiInputs.uuid(property);id=ApiInputs.uuid(id);allowed(actor,property,false);return stored(property,id,false).view();}
    private String text(JsonNode b,String field,int max,boolean required){var n=b.get(field);if(n==null||n.isNull()){if(required)throw ApiInputs.bad(field+" required");return null;}if(!n.isTextual()||n.asText().strip().length()>max||required&&n.asText().isBlank())throw ApiInputs.bad("Invalid "+field);return n.asText().isBlank()?null:n.asText().strip();}
    private record Metadata(String type,String number,LocalDate date,String owner) {}
    private Metadata metadata(JsonNode b,View previous){if(b==null||!b.isObject())throw ApiInputs.bad("Expected metadata object");var fields=Set.of("documentType","documentNumber","issueDate","ownerName");b.fieldNames().forEachRemaining(k->{if(!fields.contains(k))throw ApiInputs.bad("Unknown legal field");});
        String type=b.has("documentType")||previous==null?text(b,"documentType",40,true):previous.documentType();if(!Set.of("LAND_USE_RIGHT","HOME_OWNERSHIP","SALE_CONTRACT","OTHER").contains(type))throw ApiInputs.bad("Invalid documentType");
        String number=b.has("documentNumber")||previous==null?text(b,"documentNumber",150,false):previous.documentNumber(),owner=b.has("ownerName")||previous==null?text(b,"ownerName",150,true):previous.ownerName();LocalDate date=previous==null?null:previous.issueDate();
        if(b.has("issueDate")){try{date=b.get("issueDate").isNull()?null:LocalDate.parse(text(b,"issueDate",10,false));}catch(RuntimeException e){throw ApiInputs.bad("Invalid issueDate");}}if(date!=null&&date.isAfter(LocalDate.now(ZoneOffset.UTC)))throw ApiInputs.bad("Future issueDate");return new Metadata(type,number,date,owner);
    }
    private void parentLock(String id){jdbc.queryForObject("SELECT id FROM properties WHERE id=? FOR UPDATE",String.class,id);}
    private void version(View v,int expected){if(expected<1||expected==Integer.MAX_VALUE)throw ApiInputs.bad("Invalid expectedVersion");if(v.contentVersion()!=expected)throw ApiInputs.conflict("Document changed");}
    @Transactional public View upload(Long actor,String property,JsonNode body,MultipartFile input){property=ApiInputs.uuid(property);allowed(actor,property,true);parentLock(property);allowed(actor,property,true);if(jdbc.query("SELECT id FROM property_legal_documents WHERE property_id=? AND deleted_at IS NULL FOR UPDATE",(r,n)->r.getString(1),property).size()>=10)throw ApiInputs.conflict("Maximum 10 legal documents");var m=metadata(body,null);var validated=files.validate(input,true);if(validated.mimeType().equals("application/pdf"))pdf.validate(validated.bytes());var saved=files.store(validated);String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO property_legal_documents(id,property_id,uploaded_by,document_type,document_number,issue_date,owner_name,storage_key,original_filename,mime_type,size_bytes,sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id,property,actor,m.type(),m.number(),m.date(),m.owner(),saved.key(),validated.originalFilename(),validated.mimeType(),validated.bytes().length,validated.sha256());audit.record(actor,"LEGAL_DOCUMENT",id,"LEGAL_UPLOADED","PENDING",1);return stored(property,id,false).view();}
    @Transactional public View patch(Long actor,String property,String id,int expected,JsonNode body){property=ApiInputs.uuid(property);id=ApiInputs.uuid(id);allowed(actor,property,true);var old=stored(property,id,true).view();version(old,expected);var m=metadata(body,old);jdbc.update("UPDATE property_legal_documents SET document_type=?,document_number=?,issue_date=?,owner_name=?,content_version=content_version+1,status='PENDING',reviewed_by=NULL,review_reason=NULL,reviewed_at=NULL,updated_at=UTC_TIMESTAMP(6) WHERE id=?",m.type(),m.number(),m.date(),m.owner(),id);audit.record(actor,"LEGAL_DOCUMENT",id,"LEGAL_UPDATED","PENDING",expected+1);return stored(property,id,false).view();}
    @Transactional public void remove(Long actor,String property,String id,int expected){property=ApiInputs.uuid(property);id=ApiInputs.uuid(id);allowed(actor,property,true);var old=stored(property,id,true).view();version(old,expected);jdbc.update("UPDATE property_legal_documents SET deleted_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6),content_version=content_version+1 WHERE id=?",id);audit.record(actor,"LEGAL_DOCUMENT",id,"LEGAL_REMOVED",old.status(),expected+1);}
    @Transactional public View review(Long actor,String id,String status,String reason,int expected){access.admin(actor);ready();id=ApiInputs.uuid(id);String property=jdbc.query("SELECT property_id FROM property_legal_documents WHERE id=? AND deleted_at IS NULL",(r,n)->r.getString(1),id).stream().findFirst().orElseThrow(ApiInputs::missing);var p=allowed(actor,property,false);if(p.deletedAt!=null)throw ApiInputs.missing();if(Objects.equals(p.ownerId,actor))throw ApiInputs.forbidden();if(!Set.of("VERIFIED","REJECTED").contains(status==null?"":status)||reason==null||reason.isBlank()||reason.strip().length()>4000)throw ApiInputs.bad("Review requires status and reason");var old=stored(property,id,true).view();version(old,expected);jdbc.update("UPDATE property_legal_documents SET status=?,reviewed_by=?,review_reason=?,reviewed_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6),content_version=content_version+1 WHERE id=?",status,actor,reason.strip(),id);audit.record(actor,"LEGAL_DOCUMENT",id,"LEGAL_REVIEWED",status,expected+1);return stored(property,id,false).view();}
    public ResponseEntity<byte[]> content(Long actor,String property,String id){property=ApiInputs.uuid(property);id=ApiInputs.uuid(id);allowed(actor,property,false);var s=stored(property,id,false);return ResponseEntity.ok().contentType(MediaType.parseMediaType(s.view().mimeType())).header("Cache-Control","private, no-store").header("X-Content-Type-Options","nosniff").header("Content-Disposition","attachment; filename=\"legal-document"+(s.view().mimeType().equals("application/pdf")?".pdf":s.view().mimeType().equals("image/png")?".png":".jpg")+"\"").body(files.read(s.key()));}
}
